import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"易原卷二","description":"易原 - 易原卷二","frontmatter":{"title":"易原卷二","description":"易原 - 易原卷二"},"headers":[],"relativePath":"zh/classics/yiyuan/003.md","filePath":"zh/classics/yiyuan/003.md"}'),r={name:"zh/classics/yiyuan/003.md"};function i(n,p,c,_,o,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="易原卷二" tabindex="-1">易原卷二 <a class="header-anchor" href="#易原卷二" aria-label="Permalink to “易原卷二”">​</a></h1><p>钦定四库全书</p><p>宋程大昌撰</p><p>一五为变始，其数不定。</p><p>一水、三木受数于天而未有得乎地；二火四金受数于地而未有得乎天。若夫五，则天生之，地承之，地天于此乎交，变化于此乎起，则与向之水、火、木、金绝异矣。自有此五以后，奇耦皆变矣。向之得一者，合五为六，而水行遂成矣，以其生于阳而成阴也。向之得二者，以合为五、七，而火行亦成矣，以其生于阴而成于阳也。木三、金四之得五而成八、成九者，亦皆一理也。汉志推说五行生克，而曰「五位皆以五合，而阴阳易位」者，正指此也。 详见五行生克论。 故五位皆以生成之冲，变化之始也。非如四行之质，一受定形而遂不能流变也。方其应感，则五之气固已分播于所王之方；及其凝聚，则五之体又皆随著于赋物之地。故五能冒四，而四亦载五也。从其播而命之，则一五固可该四矣；随其著而言之，则四之成体者，亦可指为五之托体也。是以五之为数，时隐时见，而多少不可得齐也。河图一之，是示其生于本数，而寓其成于四行也。洛书有五而又有十，则本其生以为已生，而收四行之成以为已成也。则其多少不齐，皆不害其为纪实也。大衍者，本五行之数而通其变，故虽依并五行，而非正以五行为用也。故五十数者，所以多于图而减于书也。至此则当从设数求之，不可概泥定数也矣。 设数本数详见论数 二。土之立数不常，</p><p>河图之一其五者，何也？四宗乎五，故成并于生也。土之生也，受其奇于天，而会其耦于地。其孑然而独立也，以至该之体，擅至中之位，故能四而受感，分气而应也。播于四时，散于万物，无所不蔇，亦无不徧，遇水火则与之为水火，值金木则与之为金木，气分于此，质成于彼。故凡四之成材者，皆五之委形也。所谓寄旺四季者，正其凡最也。故成数可以并乎生数也。图之特出一五而寓成于八列，不自著十者，正以此也。天地所布，洛书所画，既有一五，又则出二五者，何也？一五之君四气也，其理固无异于河图也。然而四气得五而变，数既增多，四行亦益闳大，则其增立二五，正收四行之成而总之于己也。百昌皆生于土而反于土，人物禽兽凡有形质而粲然神奇，莫不终于臭腐而复乎壤地也。所谓「木落还粪其本」者，特从速化而易见者举以为况耳。类而推之，何时而不有此物，何物而不复乎此土也。则土虽不能自生其质，而四材亦能与之为质也。是虽下同四行受五之例，而两其五以识成，亦有其理也。三、五行主五遗十</p><p>一五中土授四行以生而不居其成，此正理也。土无生土之理，故五土之数不当更增二、五也。天地洛书，土皆有十，而图独无十者，五能变而十不能变也。图之所主者，制变也。十隐于四行之八，八者可见而十不可见。故图惟一、五也，不曰自一而万，无所用十也。若究求制变之元，则一、五之外尚无二、五，况可重之以及于三、五也乎？故古书之并数言变者，皆极九而遗十也。吕氏月令即周公时训也，其繋五行于四时也，冬六、夏七、春八、秋九，皆成数也。惟中土则不十而五者，亦以变言，故不著其成也。黄帝、岐伯之讲明五德也，他皆纪成，而中土仍自纪生也。又从而明为之言曰：「五常之德，土数常生。」释之者曰：「正土不以虚加。」此最知本也。加者，一之加五而为六者也，二三、四之加五而为七、八、九者也，皆其主五而加焉者也。四行本无其成，而皆资成于土焉，故四行之数悉可随加也。若夫五之为土，则正土也。既自为土，诚使更益一土，则决不能有所孳息，故地十之十，名为虚加也。四土数不可虚加，</p><p>五行造化，其底蕴难究矣。五材也者，皆凝五德以成其质者也。从其凝以推其所从得凝，庶其可以循影想形也矣。今夫雨泉之水，五之得金，木之得土，火之得木，皆孕体于地而得此形质者，是异类能生异类之验也。九仞之山，中天之台，长城千里，其培积非不厚且多也，而常闻止篑休役之后，复有毫毛增长，如世传息壤之怪乎？则同类不能自相生育，其验甚明也。其曰正土不以虚加者，言因土得形，而可以形加者，皆非正土也。故天五可以总变，而地之二其五者不能也。黄岐之论又曰：「天有九宫，不可至十。」九宫云者，五行游变之方也，正并图之九位而立为此名也。故循五行而言者，常至九而极也。盖洪范之言五行也，咸、酸、苦、辛、甘者，五材之已成五味者也。既其成味，则不可复指为生矣。然其列叙五数，则水一、火二、木三、金四、土五，遂皆舍其成而言其生也，是亦黄、岐、周公之意也。及其著稼穑于土行，而反援润下、炎上、曲直、从革四者以自例，正欲著其重谷之意，以成养民之德焉耳。然而稼穑出于人力，终不与炎、润之类实为本性者同也。故四行之凝聚也，其有性可名者，率能蔽以一言，曰炎、曰润之类是也。而「土爰稼穑」云者，于是乎可稼可穑焉耳，此即因其实而别言之者也。禹于此亦遂别创一𬂠，出五行之外，而命为六府，知其不可强以传致也。然则五行也者，禹能增一谷而六其五矣，终不能正归其甘于土，此非不可虚加之类耶？五：太玄无。十：</p><p>太玄五行，其生成位置全与洛书数合。其言曰：「一与六共宗，二与七共朋，三与八成友，四与九同道。」夫宗朋友道，皆以耦言也，正今图之生成相袭者也。其成数多于生数，则皆经五而加焉者也。若夫五五相守也者，揆以今图，则其一列已自为五，其一列又自为十，不止于两五而已也。雄以五五之外不言更有余数也，岂有隐天五于数总，而独析地十以为两五也耶？然雄之书有五无十者，触类皆是也。充其三方而九之，九九而八十一，是其具九赞以成其为元者也，而九赞亦遂尽九而止，不更演也。至于四行记数，则水火木金皆兼生成两数也。土之五五虽尝骈立两五，亦不正名为十也。其意实存能变之五，而不主不变之十也。又其推天地人体属序之类，皆至九而极，则雄其有得于列子究九者欤？而古之名事名物率以九纪，又可触类而推也。六、古数主九：</p><p>上古之世，治道人事多以九名，如三皇之世，九邱、九扈；尧禹之世，九州、九官、九畴、九歌、九德、九鼎、九功、九共，黜陟之用九载，箫韶之极九成，皆九也。六以十竟也。周制之存乎周官者特详矣，而九职、九赋、九式、九贡、九两、九仪、九命、九夏、九筮、九祭、九掺、九伐、九畿、九服，皆不于十取数也。总而言之，则六卿、六属，己象天道，而必增三孤以为九卿，亦其理也。九州虽尝患其太广，析为十二，无何复九，终三代不能易也，此亦一理也。又如九畴之别类也，咎证、休证既已合为一畴，五福、六极又复合为一畴，推原其意，殆谓吉凶虽反，而事类正同，故合二为一无碍也。然则「五事」即五行之在人者矣，「三德」即「皇极」之应变者矣，则夫「五事」之与五行，「皇极」之与「三德」，亦当合为两畴矣，而何以遂离为四也哉？用此理以推禹意，则夫九畴矣，或离或合，义例不同，而必欲迁就以成为九焉耳也。古人尊九，乃不谋而同如此哉！说</p><p>右列子言一变为七，七变为九，盖以天一至天九者言之也。水火木金土皆有形矣，而水居其首，故一为形变之始也。形变至九，则天五之气周行乎四德者，已极乎此，不可他变，故曰「九者，究也」。按列子作九变者究也。九复变一，则金实生水也，金九而水一故也。若夫轻清而上为天，重浊而下为地，则其别自更端以言人事者耳。故继之曰「冲和气者为人」也。则列子之指形变，盖自天一而始也。八、列子言河图</p><p>列子之言数变曰：易变而为一，一变而为七，七变而为九。九者，究也，复变为一，一者形变之始也。此正疏说太极不入形变，而河图数当极九者也。此之谓一，盖实天一之一，而非太极之一也，是取其已形者而言之也。至夫易无形埒也者，乃始正指未形之太极也。易者，夷易之谓也，非变易之易也。天地已判，乃始有形，故一为变始，而夷易无形埒之地，方且混沦无朕也，则安得有变可言，有一可数也？夫非太极而孰能与此也？ 张湛释列子至形埒之语云：「不知形下一字，按字书读如郛，以耕田起土为义。其曰易无形埒，则直混然而已，太极之混成浑沦者是矣。 及乎夷易无形埒者，又动而至于可以生物也。则天也者，实为形始；而一也者，实为数始也。至此而后，其形埒始著也。故夷易所变之一，乃为有形之一，而太极浑沦者，未尝著形，而亦未及乎变也。九、列子言河图一遽变七，七遽变九，九复变一。诸家皆知其为易发理，而无有能言其宿者，惟张湛之言为得也。曰：一变为七、九，不以次数者，全举阳数领其都会也。夫一、三、五、七、九者，阳之全数也；二、四、六、八者，阴数之对变，而包乎阳数之内者也。既其从阳数之会，举一、七、九以该三、五，则夫二、四、六、八亦皆包乎阳变之内矣，不待枚数也。若夫十土，非不预变也，能生成四行，而不肯自为四行，故仗五以出变，而十之为数，遂暗寓乎四生四成之列也。是以数变者，以九为极也。以天地十数之效乎四时者观之，冬水、春木、夏火、中土、秋金，即其一、三、七、五、九形变之序矣。秋之金，其数九，而九不变十也，乃复变水，水之数一，是九复变一也者，复从形变之初，循环再起者也。故凡列子此语，专以发明太极之无数，而河图之无十者也。若用无形埒之夷易， 以豉反。 以为变易之易， 音亦。 则失之远矣，而理亦不贯也。」盖列子此语，惟从易理以求，则遂可晓，而舍易则无见也。予尝深探老氏一教，见其纲条悉自易出，而其徒相与极口诋訾孔子，则遂疑其尝见繋辞、太极、两仪之序，而耻其不能终成一家，则遂立诋以自文也。 详见易老通言。</p><p>十、五行生位，本是王位，</p><p>谓天地五初数为五行初度，后五数为五行增数，古固有知之者矣。至其名先五为生，名后五为成，则至汉人实始详言也。然而四气所生，自直亥、寅、已、申，而一、二、三、四之直子、午、卯、酉者，乃四气王地耳。然则汉儒何所取则，而万世何以无议也？是特主五以推变化，而不专为四气发凡也。盖裨灶占陈以五德言之，谓其兴复之数当在五。故汉儒训释其义曰：「天以一生水，地以二生火，天以三生木，地以四生金，天以五生土。五位皆以五而阴阳易位，故曰妃以五成也。然则水之大数六，火七，木八，金九，土十也。」凡其言五行生成，至此而加详矣。审求其理，实皆以变五为成，而四时生王非所专主也。若从五行生成而推易数之生成，则泥矣。十一、八卦无土卦图</p><p>地六，水坤地四、金兑天九、金乾</p><p>地二，火离天一，水坎</p><p>地八，木巽天三，木震天七，火艮</p><p>十二、八卦不立土卦。</p><p>四行之在卦也，其有数可数者，巽八震三之为木，离二艮七之为火，兑四乾九之为金，坎一坤六之为水。总而计之，则为四者凡十。是四行生成，短长相补，合而数之，可及四十矣。至夫天五地十也者，四行依之以成其体者也。乃遂无卦可立，无数可推，以较天地图书，不独无十，亦且无五矣。此正大衍受河图减五之则，而定著以为卦数者也。夫五之无也，岂其八卦自能变化也哉？土之施德乎四象，己成功用，至于可爻可卦，则五也，十也，皆藏乎四象已成之画矣。观易者苟其于此有见，则夫卦之六十有四者，虽无主土专立之卦，而爻之三百八十有四者，亦无一爻焉，而能不载乎土也，安用局乎卦爻，而下与四行同体也哉？故说卦枚数八，列名数，而曰「此其秋也，此其水也」。曰秋者不过域乎四时，曰水者不能外乎四德也。而土也，元不隶时，亦不著德以见其该也。及夫卦之已成，则不问何卦，凡六其爻者，率皆指五以为宗主，则五亦不能终藏也。此其致甚邃也。予既得此理矣，于是始从无卦无爻之地，而探求夫天五地十之所存也。</p><p>十三、八卦，分载土德，土之用事，回复隐显，不主故常。故自图、书以及大衍，立数写肖，则皆时多时少，不可准度。说者病其无居，则遂依时日以立分际。故其言曰：「土王四季，各十八日。」此其为说，盖深明乎四行之载土，而土五之能冒四也。故于一时之九十日者，五分而取其一，以为土日也。合四时所取各十八日，而絫数之，则其为日，盖七十有二也。积七十二者五，而为当期之日，则是土之一德，亦常居其五一也。此其分际，确乎其能得五土该四之分矣。第其于四季中㓼取一十八日以为土日，则或执而不通焉耳。 详见后篇。 然其意可师也。若能放之，而求土数于分五隐一之地，则五虽不自立卦，而卦皆涵五也。惟夫读易者，得其言而不得其所以言，乃遂欲以三百八十四爻者，均配乎三百六十日，于是以一爻配对一日，而余遗二十四爻，无日可配，则又多方其说，而反以汨易也。</p><p>十四分爻当日，遂至别异四卦</p><p>分爻当日，皆经生以意言之，初无易据也。其说或曰「乾坤、坎离者，天地日月也」，或曰「坎离、震、兑分主四气而运行之」，不自囿于五行也。或曰八初卦之爻既为卦祖矣，及其叠初卦以为重卦也，本气用尽而他气迭起，则夫八纯卦之本爻不更入用也。说凡三变，而皆黜除卦象，乃得傅会乎二十四爻之不用也。此其为皆不通也。且以易类推之，乾坤之有用九用六也，为夫六爻不足以尽其意，而遂别设二用以救亢战之过也。则八八相承而为六十四爻者，卦之与爻率皆相须以承四气，安有虚卦虚爻不丽于用者耶？且其谓乾坤不用，犹其稍稍并本矣。坎离者，水火也，冬夏也，何为而不入于用也？若曰水火者日月也，日月可以该冒他卦，则震雷巽风，其用狭于日月，而水火二象亦何从而得专生成也？若曰「阴阳之义配日月，日月者，阴阳之著象，而可该他卦者也」，则夫山泽通气，气非阴阳也乎？「雷风相薄」，雷风非阴阳而孰与为体也？至谓震离、坎、兑分位四正，可该他卦，则乾坤岂不该于四气也耶？夫乾、坤两卦不止六爻皆用，而乂增设两辞以极其至，则四卦之爻安得不用也？又谓八卦本气不用，可虚诸用外，则夫八初卦也者，皆以六爻入诸六十四重卦，则既分应气，令无一画可除也。夫既无画可除，则其本气何尝用尽也？凡此数者，皆易之大节也，而其无宿且犹如此，予故详思其以，而得其致误之由也。盖夫子之言策也，曰：「乾坤之三百六十者，可以当一期之日也。」此其所指，则乾坤十二爻之策也，初无与乎六十二卦之爻也。若其策之在卦，则夫万有一千二百五十者，夫子明以配对万物，而未尝用以配日也。此其为误，自当质夫子而正之，不当袭误生误也。十五分日应五行，</p><p>累四时之日，而每季取其十有八者，以为土王之日，其为分四载五之理，固甚邃矣，而分日寄王之说则泥也。姑以春序而例其余，则可见矣。木德用事，则凡九十日发生者，莫非春也。孰使春而能出此之生，则土德其实为之也。凡其死者茁，枯者荣，则春固有象矣。而土之授春以生者，漠乎其无朕也。苟欲于九十日之末，㓼取十有八者，而曰此土德之寄旺乎四季者也。则又当别存七十二者，而曰此木德之实旺者也。其说若可听矣。不知立何为际，而名何日以为土王也。又不知十八日者，安得别有奇力，以自表乎木德之外，而云不为木王之日也。然则十有八日云者，吾知其说矣。约其分际，犹曰五德者，率五而均计，则土力当居其一也。惟其日之三百六十者，分当为一期，故其分际可数，因得借之以谕率分焉耳。若师其意，通其泥，常于土德隐而不见之地，五分四德而取其一以明土力，则凡五之能该四也，四之当载五也，皆有宿矣。而三百八十四爻者，亦可随卦当时而无所赘亏。凡其傅会之说，皆遂可彻也。十六立分当日，</p><p>十六卦而当一时，则此之九十六爻者，皆当随时用事。如在春则皆为木德，而在夏皆为火德，其类可推也。积而致之，岁竟则四其三月者，月仍各以九十六爻为四德分王之日，而土德之居五一者自在其中也。盖四德也者，无一日焉可以离土，则是三百八十四爻也者，亦无一爻焉而能不载乎土也。土之兼冒四时也，其力虽散而薄，然而合四时之薄以概一时之王，则总三百八十四爻之力，土当据其爻之七十六而奇也。此非袭其旧失，而专以爻计之无所寄，而均计之无所寄算，姑此率爻而言也。若夫当日之卦，则自有定位矣。卦有定位，则爻亦随卦以隶乎四时也。以此立则是每卦每爻悉皆有土，不至如分爻之执泥也。十七、六日七分，</p><p>分爻起于爻卦，而卦之当日也，其说出于易纬，谓以六十卦而分直三百六十五度，四分度之一也。一卦而当六日，则六十卦已为三百六十日矣。然尚余五日以及四分日之一者未有所宿，则遂用此之五日有奇者，析一日以为八十分，积四百二十分，而五日有奇者乃始有宿也。故六十卦者，既皆全受六日，又当别受七分也，此其所从以为六日七分之则也。后人因而推广之，则不止分卦而已也，乃遂至于分爻也。然尝审而求之，则知其破碎无理，当不足尚矣。何者？秋冬之气不可以入之春夏，亦犹阴卦之爻不可入诸阳卦也。今也不分四季之屈信，不立八卦之分际，概以一日析为八十分，而凡卦均受七分，固可以传足乎周天之度矣。而其大不通者，势必至于分爻以出卦外，则必有卦阳而爻阴者矣，亦有卦阴而爻阳者矣，其为破碎不待多辨也。</p><p>十八分爻记月之误</p><p>一卦而均传七分，积十一卦有奇而八十分始足，则是合六十七八爻之余分，始能共当一日矣。然而推之不通也。自垢至坤，凡卦皆趋乎坤，则皆阴能消阳之卦也。自复至乾，凡卦皆趋乎乾，则皆阳能消阴之卦也。卦能消阳，则其爻不能以直乎阳，卦能消阴，则其爻不能以直乎阴，此不难见也。今其积八十分以为一日也，法当跨涉两月，则其六十七八爻者，亦当通十一二卦而参取也。设若时月适在姤复之交，则夫十一二者必有以阴卦阴爻而直阳日者矣，亦有以阳卦阳爻而遂直阴日者也。此乃自用其分爻之指，以明分爻之失，而破碎卦体，乃遂至此，他固不足深论也。易原卷二。</p>',27)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
